dtsPropsFor.CaseHero:
project: {
  slug: string;
  eyebrow: string;
  title: string;
  /** Resumo curto (1-2 frases), usado no card de hover da Paisagem. */
  description: string;
  meta: { cliente: string; setor: string; tipo: string; ano: string };
  heroImages: string[];
  overview: { heading: string; body: string[]; challenge: string };
  gallery: string[];
  /** "published" (default) e clicavel; "coming-soon" mostra "Em breve". */
  status?: "published" | "coming-soon";
  /** Dominio exibido na barra do BrowserFrame. */
  siteUrl?: string;
  /** Screenshots do card de hover. `card` e o recorte 760x874 da grade. */
  preview?: { desktop: string; mobile: string; card?: string };
  /** Dirige a cor do apex do fragmento. Omitido = "institucional". */
  type?: "institucional" | "landing" | "webapp" | "ecommerce";
  stack?: string[];
  /** Recortes de secao para a grade "As Telas". */
  sections?: string[];
  /** Presente = a pagina de case renderiza CaseShowcase. */
  mockups?: { desktop3d?: string; mobile3d?: string; browser?: string; phone?: string };
  /** Cores da marca do site capturado; tingem o gradiente do CaseShowcase. */
  palette?: string[];
};

